from pathlib import Path
import html as htmllib

out=Path(r'D:/WorkBuddy工作区/04-工具与技能/02：安装skill/《语法讲义》逐章交互页')
out.mkdir(parents=True,exist_ok=True)
chapters=[
('01','语法单位','语素、词、词组、句子的层级，以及单独成句、替换、扩展三个判定标准。','语素 → 词 → 词组 → 句子','综合证据，不凭单一标准判断词与词组。','理发、手表、买书、白菜'),
('02','词的构造','重叠、附加、复合三类构词方式；复合词与句法结构的边界。','重叠 + 附加 + 复合','先确认语素，再看语素之间的构造关系。','妈妈、看看、站着、刀子、手表'),
('03','词类','以分布为标准划分词类，处理共性、个性和兼类。','词类 = 分布位置 + 组合能力','意义可作参照，真正的分类依据是形式分布。','学习、漂亮、今天、很、的'),
('04','体词','名词、处所词、时间词、方位词、量词和区别词。','体词系统：人/地/时/方/量/别','观察能否作主语、宾语、定语，以及能否受数量修饰。','北京、昨天、桌上、三个、男'),
('05','谓词','动词与形容词的分类、及物性和重叠式。','谓词 → 动词 / 形容词','关注带宾语能力、程度修饰和重叠形式的分布差异。','看书、很高兴、看看、干干净净'),
('06','代词','人称、指示、疑问代词及其指代功能。','代词 = 语境中的指代接口','代词的意义需要结合说话场景、指称对象和句法位置。','我、你、他、这、谁、什么'),
('07','主谓结构','主语与谓语的性质；结构位置不等于施受语义角色。','主语 + 谓语','不要把主语直接等同于施事，也不要把宾语直接等同于受事。','我骑车、自行车修好了、速度很快'),
('08','述宾结构','宾语类型、粘合式与组合式、准宾语和双宾语。','述语 + 宾语','先判断述语与宾语的组合关系，再辨认受事、结果、处所或施事角色。','洗衣服、进城、来客人、给我一本书'),
('09','述补结构','两个“得”字之分、补语类型及述补结构的及物性。','述语 + 补语','补语说明动作结果、趋向、可能、程度或状态。','洗干净、走进去、看得见、说不清'),
('10','偏正结构','定语与状语的区分，粘合式与组合式。','修饰语 + 中心语','中心语是体词时常为定语，中心语是谓词时常为状语。','白马、木头房子、很新鲜、赶快走'),
('11','联合结构','连接手段、体词化和分配律。','成分A + 成分B + …','联合项地位平等，项数可以超过两个；注意连接词与整体功能。','北京、上海、广州；又快又好'),
('12','连谓结构','V₁+N+V₂的分析及对兼语说的辨析。','动作1 + 动作2','判断两个谓词之间是先后、方式、原因、条件还是目的关系。','下课开会、拍手笑、上街买菜'),
('13','介词','介词的虚化来源以及“把、在、给”等用法。','介词 + 名词性成分','介词引出处所、对象、工具、受事等成分，不能简单按动词处理。','在北京、给我、把书放桌上'),
('14','副词','副词与形容词的鉴别及副词子系统。','副词 + 谓词性成分','看位置、修饰对象、能否作谓语等分布特征。','很快、已经走了、都来了、只看书'),
('15','疑问句和祈使句','句式的转换关系与句型限制。','陈述 ↔ 疑问 / 祈使','句子的功能与形式有交叉，反问句形式像疑问、功能可能是陈述。','谁来了？别说话！谁知道呢？'),
('16','语气词','语气词分类、组合层次与合音。','句末语气 + 语气层次','语气词不是简单叠加，要观察位置、组合限制与话语功能。','吗、呢、吧、啊、了'),
('17','复句','分句定位、三类联系与连词分类。','分句1 + 关系 + 分句2','先区分单句与复句，再判断并列、偏正等分句联系。','因为下雨，所以没去；虽然累，但是完成了'),
('18','省略和倒装','省略条件、倒装类型与受事主语句。','语境恢复 + 结构变位','省略必须有语境条件，倒装也要说明成分原本的结构位置。','吃过了；书我已经看完了'),
]
css='''<style>:root{--bg:#f7f4ee;--paper:#fffdf8;--ink:#25231f;--muted:#706b62;--line:#ded8cc;--red:#a84432;--blue:#3d638b;--green:#2d7965;--gold:#c99438;font-size:16px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:system-ui,-apple-system,"Microsoft YaHei",sans-serif;line-height:1.75}.wrap{max-width:980px;margin:auto;padding:0 18px}.top{position:sticky;top:0;z-index:5;background:#f7f4eedd;backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}.nav{display:flex;justify-content:space-between;align-items:center;padding:10px 0;gap:8px}.brand{font-weight:750;color:var(--red)}button{font:inherit;min-height:44px;padding:.5rem .75rem;border-radius:9px;border:1px solid var(--line);background:var(--paper);color:var(--ink);cursor:pointer}.tools{display:flex;gap:6px}.hero{padding:45px 0 30px;background:linear-gradient(135deg,#f0e3cd,var(--bg) 65%)}h1{font-size:clamp(2.1rem,6vw,4rem);line-height:1.1;letter-spacing:-.05em;margin:10px 0}.eyebrow{color:var(--red);font-weight:700}.lead{font-size:1.12rem;color:var(--muted);max-width:760px}.figure{background:var(--paper);border:1px solid var(--line);border-radius:18px;padding:16px;margin:22px 0;box-shadow:0 10px 30px #5c4a3215}.figure svg{width:100%;height:auto}main{padding:22px 0 70px}.scene{background:var(--paper);border:1px solid var(--line);border-radius:16px;padding:22px;margin:22px 0;box-shadow:0 10px 30px #5c4a3215}.scene h2{color:var(--red);margin-top:0}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.card{border:1px solid var(--line);border-radius:12px;padding:14px;background:#fbf7ef}.card h3{margin-top:0;color:var(--blue)}.flow{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:15px 0}.node{background:#ead6c2;border:1px solid #c89072;border-radius:10px;padding:9px 12px;font-weight:700}.arrow{color:var(--red);font-size:1.4rem}.lab{border:1px solid #9cb5c9;background:#edf3f7;border-radius:12px;padding:16px}.lab select{font:inherit;padding:8px;border-radius:8px;border:1px solid var(--line);background:var(--paper);color:var(--ink)}.guess{border-left:4px solid var(--gold);background:#fbf4e4;padding:15px;margin:15px 0;border-radius:7px}.answer{color:var(--green);font-weight:650}.cite{color:var(--red);font-weight:750;cursor:pointer}.quiz{border:1px dashed var(--line);padding:14px;border-radius:10px;margin:10px 0}.quiz button{display:block;margin-top:8px}.source{position:fixed;inset:0;background:#0008;display:grid;place-items:center;padding:16px;z-index:10}.box{background:var(--paper);max-width:650px;width:100%;padding:22px;border-radius:16px;max-height:85vh;overflow:auto}.box h2{color:var(--red);margin-top:0}.hidden{display:none!important}details{border-top:1px solid var(--line);margin-top:15px;padding-top:10px}summary{cursor:pointer;color:var(--blue);font-weight:650}footer{border-top:1px solid var(--line);padding:22px 0;color:var(--muted)}body.dark{--bg:#1f2527;--paper:#293033;--ink:#f2eee7;--muted:#b8b2a8;--line:#485153}body.dark .hero{background:linear-gradient(135deg,#3b3029,var(--bg) 65%)}body.dark .card{background:#30383a}body.dark .lab{background:#27363d}body.dark .guess{background:#3c3325}@media(prefers-color-scheme:dark){body:not(.light){--bg:#1f2527;--paper:#293033;--ink:#f2eee7;--muted:#b8b2a8;--line:#485153}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}@media(max-width:700px){.grid{grid-template-columns:1fr 1fr}}@media(max-width:450px){.grid{grid-template-columns:1fr}.scene{padding:16px}}</style>'''
for i,(num,title,desc,flow,core,examples) in enumerate(chapters):
    nexttitle=chapters[i+1][1] if i<17 else '全书回顾'
    cite=f's{num}'
    cards=''.join(f'<div class="card"><h3>{x}</h3><p>围绕“{x}”观察本章的形式、分布与功能，避免只凭语义直觉判断。</p></div>' for x in (examples.split('、')[:3]))
    html=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>语法讲义-{num}{title}</title>{css}</head><body><header class="top"><div class="wrap nav"><div class="brand">语法讲义-{num}{title}</div><div class="tools"><button id="minus">A−</button><button id="plus">A+</button><button id="theme">明暗</button><button id="back" hidden>回到刚才</button></div></div></header><section class="hero" data-hero><div class="wrap"><div class="eyebrow">朱德熙《语法讲义》｜第{int(num)}章</div><h1>{title}</h1><p class="lead">{desc}</p><figure class="figure" data-figure><svg viewBox="0 0 800 150" role="img" aria-label="本章核心路线图"><path d="M80 75H720" stroke="#a84432" stroke-width="4" stroke-dasharray="8 8"/><g fill="#ead6c2" stroke="#a84432" stroke-width="2"><circle cx="80" cy="75" r="45"/><circle cx="293" cy="75" r="45"/><circle cx="507" cy="75" r="45"/><circle cx="720" cy="75" r="45" fill="#d5e4df" stroke="#2d7965"/></g><g text-anchor="middle" fill="#25231f" font-size="18"><text x="80" y="82">观察</text><text x="293" y="82">切分</text><text x="507" y="82">比较</text><text x="720" y="82">解释</text></g></svg></figure></div></section><main class="wrap"><section class="scene" data-scene="1"><h2>场景 1｜本章主线</h2><div class="flow">{''.join(f'<span class="node">{x}</span><span class="arrow">→</span>' for x in flow.split(' + '))}<span class="node">章节结论</span></div><p>{core}<sup class="cite" data-cite="{cite}">[原文]</sup></p><div class="guess" data-guess><b>先猜再看：</b>本章最需要优先观察的是“意义”还是“形式分布”？<button onclick="this.nextElementSibling.hidden=false">揭晓</button><p class="answer" hidden>先观察形式分布，再结合意义解释。朱德熙的基本方法是“以结构为纲、以意义为参照”。</p></div></section><section class="scene" data-scene="2"><h2>场景 2｜概念卡片</h2><div class="grid">{cards}</div><details><summary>展开：分析提醒</summary><p>同一个词语进入不同结构后，可能承担不同的语法功能；同一种意义也可能由不同形式表达。分析时应把位置、组合能力和句法层次记录下来。</p></details></section><section class="scene" data-scene="3"><h2>场景 3｜例句观察台</h2><div class="lab"><b>选择一个例子：</b><select id="ex">{''.join(f'<option>{htmllib.escape(x)}</option>' for x in examples.split('、'))}</select><p id="out">请选择例句，观察它的结构位置、搭配限制与语法功能。</p></div><p>当前章的学习任务：把例句拆成可观察的形式证据，并说明它与相邻结构的差异。<span class="tag">语料观察</span></p></section><section class="scene" data-scene="4"><h2>场景 4｜方法与相邻章节</h2><p>本章不是孤立知识点。它承接前一章的分析基础，并为下一章“{nexttitle}”提供观察工具：先确定单位和结构，再判断功能与意义。</p><details><summary>展开：不要混淆的两组概念</summary><p>结构位置不等同于语义角色；形式相似不代表功能相同；可以进入同一位置也不代表内部构造完全一致。</p></details></section><section class="scene" data-scene="5"><h2>场景 5｜你答得上来吗？</h2><div class="quiz" data-quiz><b>1. 本章的核心分析对象是什么？</b><button onclick="this.nextElementSibling.hidden=false">查看答案</button><p class="answer" hidden>{title}中的形式单位、组合关系和分布限制。</p></div><div class="quiz" data-quiz><b>2. 为什么不能只靠语义下结论？</b><button onclick="this.nextElementSibling.hidden=false">查看答案</button><p class="answer" hidden>因为同一意义可能有多种形式，同一形式也可能因结构和语境而产生不同功能。</p></div><div class="quiz" data-quiz><b>3. 下一步怎么读？</b><button onclick="this.nextElementSibling.hidden=false">查看答案</button><p class="answer" hidden>回到例句，标出成分位置、组合限制和结构层次，再用章节术语复述。</p></div></section><footer>本页依据《语法讲义》研读底本与读书笔记整理。原笔记未提供可靠对应页码，出处账本暂标“页码待核对”。</footer></main><div class="source hidden" id="source"><div class="box"><button id="close" style="float:right">关闭</button><h2 id="st">出处核对</h2><p id="sq"></p><p>本页内容为依据原始底本与读书笔记的学习性转述，页码待核对。</p></div></div><script>const $=s=>document.querySelector(s);let SOURCES={{'{cite}':{{t:'第{int(num)}章：{title}',q:'本页依据《语法讲义》第{int(num)}章研读底本与读书笔记整理。'}}}};document.querySelectorAll('.cite').forEach(e=>e.onclick=()=>{{let s=SOURCES[e.dataset.cite];$('#st').textContent=s.t;$('#sq').textContent='原文/笔记入口：'+s.q;$('#source').classList.remove('hidden')}});$('#close').onclick=()=>$('#source').classList.add('hidden');$('#source').onclick=e=>{{if(e.target.id==='source')$('#source').classList.add('hidden')}};$('#ex').onchange=e=>$('#out').textContent='已选：'+e.target.value+'。请记录它的结构位置、组合限制和语法功能。';let scale=1;$('#minus').onclick=()=>{{scale=Math.max(.9,scale-.05);document.documentElement.style.fontSize=scale+'rem'}};$('#plus').onclick=()=>{{scale=Math.min(1.2,scale+.05);document.documentElement.style.fontSize=scale+'rem'}};$('#theme').onclick=()=>document.body.classList.toggle('dark');try{{let y=localStorage.getItem('grammar-{num}-y');if(y&&confirm('继续上次阅读位置？'))scrollTo(0,+y);addEventListener('scroll',()=>localStorage.setItem('grammar-{num}-y',scrollY),{{passive:true}})}}catch(e){{}}</script></body></html>'''
    (out/f'语法讲义-{num}{title}.html').write_text(html,encoding='utf-8')
